"""Replace the real Azure OpenAI endpoint host in the committed Task B evidence with a placeholder.

Every record stores ``endpoint_host`` so ``build_router_report.py`` can prove
all 1880 requests went to one resource. Publishing the real host adds nothing
to that proof, so this script rewrites it in:

* ``outputs/evidence_router_<run>.json.xz``        (re-packed; archive SHA256 changes)
* ``outputs/raw_fulltext/router_<run>.jsonl``      (full model answers, if retrieved)
* ``outputs/router_<run>.metrics.jsonl``           (regenerated by the builder anyway)

Per-record ``response_sha256`` values hash ``response_text`` only and stay valid;
run ``scripts/verify_router_fulltext.py`` afterwards.

Usage:
    python scripts/redact_router_endpoint.py --host <real-host> [--placeholder YOUR-ENDPOINT.cognitiveservices.azure.com]

Author: Xinyu Wei (魏新宇)
"""

import argparse
import hashlib
import json
import lzma
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
RUN = "20260909_223737"
OUTPUT = ROOT / "outputs"


def sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def redact_jsonl(path: Path, host: str, placeholder: str) -> int:
    text = path.read_text(encoding="utf-8")
    hits = text.count(host)
    if hits == 0:
        return 0
    redacted = text.replace(host, placeholder)
    for line in redacted.splitlines():
        if line.strip() and json.loads(line).get("endpoint_host") != placeholder:
            raise ValueError(f"{path.name}: endpoint_host was not normalised")
    path.write_text(redacted, encoding="utf-8", newline="\n")
    return hits


def redact_archive(path: Path, host: str, placeholder: str) -> tuple[str, str, int]:
    payload = path.read_bytes()
    before = sha256(payload)
    evidence = json.loads(lzma.decompress(payload))
    index = evidence["performance_columns"].index("endpoint_host")
    hits = 0
    for row in evidence["performance_values"]:
        if row[index] == host:
            row[index] = placeholder
            hits += 1
        elif row[index] != placeholder:
            raise ValueError(f"Unexpected endpoint_host value: {row[index]!r}")
    # Absolute VM paths carry no evidential value; keep them repo-relative.
    provenance = evidence["provenance"]
    for field in ("raw_file", "quality_file"):
        if provenance.get(field):
            provenance[field] = "outputs/" + provenance[field].rsplit("/", 1)[-1]
    raw_name = Path(provenance["raw_file"]).name
    retained = path.parent / "raw_fulltext" / raw_name
    if retained.exists():
        provenance["retained_raw_sha256"] = sha256(retained.read_bytes())
    if hits:
        provenance["redaction"] = {
            "field": "endpoint_host",
            "original_archive_sha256": before,
            "note": "raw_sha256 identifies the original VM file; retained_raw_sha256 identifies the sanitized copy.",
        }
    # Same serialisation settings as scripts/export_router_evidence.py.
    repacked = lzma.compress(json.dumps(evidence, separators=(",", ":")).encode())
    if host.encode() in lzma.decompress(repacked):
        raise ValueError("Host still present after redaction.")
    path.write_bytes(repacked)
    return before, sha256(repacked), hits


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("--host", required=True, help="real endpoint host to remove")
    parser.add_argument("--placeholder", default="YOUR-ENDPOINT.cognitiveservices.azure.com")
    parser.add_argument("--run", default=RUN)
    args = parser.parse_args()

    for name in (f"raw_fulltext/router_{args.run}.jsonl", f"router_{args.run}.metrics.jsonl"):
        target = OUTPUT / name
        if target.exists():
            print(f"{name}: {redact_jsonl(target, args.host, args.placeholder)} occurrences replaced")
    before, after, hits = redact_archive(OUTPUT / f"evidence_router_{args.run}.json.xz", args.host, args.placeholder)
    print(json.dumps({"archive_sha256_before": before, "archive_sha256_after": after, "archive_rows_redacted": hits}, indent=2))


if __name__ == "__main__":
    main()
